/**
 * Upload a chapter ZIP and create a draft. ZIP is streamed through a temp file; max size is 2GB; page count is not limited.
 * @summary Upload chapter as ZIP
 */
export const postUploadChapter = (
    postUploadChapterBody?: PostUploadChapterBody,
 signal?: AbortSignal
) => {

      const formData = new FormData();
if(postUploadChapterBody?.file !== undefined) {
 formData.append(`file`, postUploadChapterBody.file);
 }
if(postUploadChapterBody?.manga_id !== undefined) {
 formData.append(`manga_id`, postUploadChapterBody.manga_id);
 }
if(postUploadChapterBody?.chapter !== undefined) {
 formData.append(`chapter`, postUploadChapterBody.chapter.toString())
 }

      return customInstance<ResponseUploadChapterDraftResponse>(
      {url: `/upload_chapter`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData, signal
    },
      );
    }




